run=dict(schema='source66-complete-logical-review-run-v1',reviewer='/root/independent_source64',finalized_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),actual_finalizer_pid=os.getpid(),decisions=dict(source66=d,separately_reviewed_metadata_overlay=overlay),complete_named_RAW_INPUT_payload=read('RAW-input-payload.json'),analytical_evidence={n:read(n) for n in analytical},preserved_observer_negatives={f.name:json.loads(f.read_bytes()) for f in sorted(O.glob('negative.*.json'))},owned_pre_finalization_RAW_LF_bindings=pre,current_publication_binding_sha256=d['publication_binding_sha256'],current_publication_context_sha256=d['publication_context_sha256'],closure_contract=dict(whole_logical_hash='Canonical UTF8 JSON of the ENTIRE object deleting ONLY top-level run_sha256; ensure_ascii=false,sort_keys=true,separators comma colon',complete_RAW_REVIEW='review-run.json: exact full bytes, no deletion or projection; includes both complete seven-slot decisions',complete_RAW_DECISION='complete-RAW-decision.json: exact full bytes, no deletion or projection; native source decision gets external run hash after full logical run sealing',separate_RAW_INPUT='RAW-input-payload.json: complete exact finite input byte payload, not the complete review',terminal_manifest_binding='Post-finalizer/readback/close receipts and self/lease are bound by exhaustive owned manifest then CLOSED_LAST lease; immutable postclose external readback confirms exact manifest and lease bytes',no_circular_self_hash_claim=True),source_mathematical_repair=False,full_Exposition=False,PURIFIED=False)
run['run_sha256']=C(run);put('review-run.json',run)
native=dict(d);native['review_run_sha256']=run['run_sha256'];put('decision.json',native)
complete=dict(schema='source66-complete-named-RAW-DECISION-payload-v1',source66=native,separately_reviewed_metadata_overlay=overlay,complete_full_seven_slot_decisions=True,review_run_sha256=run['run_sha256']);put('complete-RAW-decision.json',complete)
pins=dict(schema='source66-distinct-complete-payload-pins-v1',whole_logical_run_sha256=run['run_sha256'],COMPLETE_RAW_REVIEW=pin(O/'review-run.json'),COMPLETE_RAW_DECISION=pin(O/'complete-RAW-decision.json'),SEPARATE_COMPLETE_RAW_INPUT=pin(O/'RAW-input-payload.json'),native_semantic_decision=pin(O/'decision.json'),actual_finalizer_pid=os.getpid(),exclusions_from_whole_logical_hash=['ONLY top-level run_sha256']);put('review-payload-pins.json',pins)
print(json.dumps(dict(actual_pid=os.getpid(),whole_logical_run_sha256=run['run_sha256'],COMPLETE_RAW_REVIEW=pins['COMPLETE_RAW_REVIEW'],COMPLETE_RAW_DECISION=pins['COMPLETE_RAW_DECISION'],SEPARATE_COMPLETE_RAW_INPUT=pins['SEPARATE_COMPLETE_RAW_INPUT']),sort_keys=True))
